UPDATE topic_catalog SET pregenerated_json = '{"story_id": "rahu_ketu_origin", "title": "राहु और केतु का जन्म", "category": "ज्योतिष कथा", "script_hi": "राहु और केतु का जन्म कैसे हुआ? समुद्र मंथन के दौरान जब धन्वंतरि वैद्य अमृत कलश लेकर प्रकट हुए, तो देवताओं और असुरों में हाहाकार मच गया। असुर अमृत पीकर अमर न हो जाएं, इसलिए भगवान विष्णु ने मोहिनी रूप धारण किया। मोहिनी ने अपनी माया से अमृत सिर्फ देवताओं को पिलाना शुरू किया। लेकिन स्वर्भानु नाम का एक चालाक असुर यह चाल समझ गया। उसने अपना रूप बदला और चुपके से देवताओं की पंक्ति में जाकर सूर्य और चंद्र देव के बीच बैठ गया। जैसे ही मोहिनी ने उसे अमृत पिलाया, सूर्य और चंद्र ने उसे पहचान लिया और भगवान विष्णु को बता दिया। विष्णु जी ने तुरंत अपना सुदर्शन चक्र निकाला और स्वर्भानु का सिर धड़ से अलग कर दिया। लेकिन अमृत की कुछ बूंदें उसके गले से नीचे उतर चुकी थीं, इसलिए वह मरा नहीं। उसका सिर राहु कहलाया और धड़ केतु। कहते हैं आज भी राहु और केतु इसी धोखे का बदला लेने के लिए सूर्य और चंद्र को निगलने की कोशिश करते हैं, जिसे हम सूर्य और चंद्र ग्रहण कहते हैं। यही कारण है कि ज्योतिष में इन्हें छाया ग्रह और रहस्य का प्रतीक माना जाता है।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "राहु और केतु का जन्म कैसे हुआ?", "image_prompt": "Cinematic wide shot of Rahu and Ketu floating in the cosmos as dark shadow planets, dark mystical aura, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "समुद्र मंथन से जब अमृत निकला...", "image_prompt": "Gods and demons churning the cosmic milky ocean, golden Amrita pot glowing, epic mythological lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "विष्णु जी ने मोहिनी रूप धारण किया।", "image_prompt": "Lord Vishnu taking the form of beautiful Mohini holding the golden pot of nectar, divine glow, ancient Indian art style, 9:16", "approx_sec": 6.0}, {"slide_index": 4, "caption": "स्वर्भानु नाम का असुर चाल समझ गया।", "image_prompt": "A cunning demon Swarbhanu looking suspiciously at Mohini, dark background, intense eyes, realistic myth art, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "वह सूर्य और चंद्र के बीच बैठ गया।", "image_prompt": "Demon in disguise sitting between Surya (Sun God) and Chandra (Moon God), glowing deities, tension, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "सूर्य और चंद्र ने उसे पहचान लिया!", "image_prompt": "Sun and Moon gods looking shocked and pointing fingers at the disguised demon, dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "विष्णु जी ने सुदर्शन चक्र चलाया...", "image_prompt": "Lord Vishnu angrily throwing the spinning, fiery Sudarshana Chakra, intense action, sparks flying, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "और स्वर्भानु का सिर धड़ से अलग कर दिया।", "image_prompt": "The glowing Sudarshana Chakra slicing through the neck of the demon, cosmic background, mythological drama, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "लेकिन वह अमृत पी चुका था।", "image_prompt": "The severed head of the demon glowing with the power of immortal nectar, starry night sky, eerie, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "सिर राहु बना और धड़ केतु।", "image_prompt": "One floating demonic head (Rahu) and one headless serpent body (Ketu) floating in space, astrology concept, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "आज भी वह सूर्य-चंद्र को निगलने की कोशिश करते हैं।", "image_prompt": "A massive shadow demon trying to swallow the glowing sun, solar eclipse happening in the background, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "जिसे हम ग्रहण कहते हैं।", "image_prompt": "A beautiful but eerie total solar eclipse viewed from ancient India, dark silhouette, cosmic, 9:16", "approx_sec": 4.0}]}' WHERE id = 'rahu_ketu_origin';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "gita_karma_yoga", "title": "कर्मण्येवाधिकारस्ते का सच्चा अर्थ", "category": "श्रीमद्भगवद्गीता", "script_hi": "कर्मण्येवाधिकारस्ते का सच्चा अर्थ क्या है? कुरुक्षेत्र के युद्ध में जब अर्जुन ने अपने ही सगे-संबंधियों को सामने देखा, तो वह टूट गए। उनके हाथ से गांडीव धनुष गिर गया। तब भगवान श्री कृष्ण ने उन्हें गीता का उपदेश दिया। कृष्ण ने कहा, ''हे अर्जुन! तुम्हारा अधिकार केवल कर्म करने में है, उसके फल में नहीं।'' इसका मतलब यह नहीं है कि हमें फल की चिंता ही नहीं करनी चाहिए। इसका असली मतलब है कि जब हम फल से बहुत ज्यादा आसक्त हो जाते हैं, तो हम अपना वर्तमान कर्म बिगाड़ लेते हैं। यदि तुम सिर्फ इस बात पर ध्यान दोगे कि जीत मिलेगी या हार, तो तुम युद्ध लड़ ही नहीं पाओगे। इसलिए अपना सर्वश्रेष्ठ प्रदर्शन करो और परिणाम मुझ पर छोड़ दो। जीवन में भी यही सच है। हमारा नियंत्रण केवल हमारे प्रयासों पर होता है, नतीजों पर नहीं। यही निष्काम कर्म योग है, जो इंसान को हर चिंता और भय से मुक्त कर देता है।", "estimated_speech_sec": 70.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कर्मण्येवाधिकारस्ते का सच्चा अर्थ?", "image_prompt": "Lord Krishna and Arjuna on the chariot in Kurukshetra battlefield, glowing divine aura, epic Mahabharata scene, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "कुरुक्षेत्र के युद्ध में जब अर्जुन टूट गए...", "image_prompt": "Arjuna looking sad and dropping his Gandiva bow on the chariot, armies in the background, dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "अपनों को सामने देखकर वह मोह में पड़ गए।", "image_prompt": "Arjuna looking across the battlefield at Bhishma and Drona, conflicted expression, cinematic fog, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "तब भगवान श्री कृष्ण ने उपदेश दिया।", "image_prompt": "Lord Krishna smiling calmly and speaking to Arjuna, cosmic light radiating from Krishna, masterpiece art, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "तुम्हारा अधिकार केवल कर्म करने में है...", "image_prompt": "Close up of Krishna''s hand in a teaching mudra, glowing golden energy, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "उसके फल में नहीं।", "image_prompt": "A beautiful blossoming lotus flower in muddy water, symbolizing detachment, soft lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "इसका मतलब फल की चिंता छोड़ना नहीं है।", "image_prompt": "A modern or ancient warrior focusing intensely on sharpening his sword, deep focus, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "बल्कि फल के मोह से मुक्त होना है।", "image_prompt": "A person walking on a glowing path of light towards a temple, peaceful atmosphere, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "जीत या हार के बारे में सोचोगे...", "image_prompt": "A balance scale weighing a golden crown and a sword, dramatic shadows, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "तो अपना वर्तमान कर्म बिगाड़ लोगे।", "image_prompt": "An archer missing the target because he is looking away, symbolic representation, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "सर्वश्रेष्ठ प्रदर्शन करो और परिणाम मुझ पर छोड़ दो।", "image_prompt": "Arjuna picking up his bow with renewed confidence, glowing eyes, ready to fight, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "यही निष्काम कर्म योग है।", "image_prompt": "A serene meditating figure with the cosmos swirling around them, inner peace, spiritual, 9:16", "approx_sec": 4.0}]}' WHERE id = 'gita_karma_yoga';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "shiva_third_eye_kama", "title": "भगवान शिव का तीसरा नेत्र", "category": "शिव पुराण", "script_hi": "भगवान शिव का तीसरा नेत्र कब और क्यों खुला? सती की मृत्यु के बाद भगवान शिव गहरे ध्यान में चले गए थे। दूसरी ओर, तारकासुर नाम के असुर को वरदान था कि उसे सिर्फ शिव का पुत्र ही मार सकता है। देवताओं ने शिव जी का ध्यान तोड़ने के लिए कामदेव को भेजा। कामदेव ने अपने फूलों के बाण शिव जी पर चलाए, जिससे उनके मन में प्रेम की भावना जाग गई। लेकिन अपनी तपस्या भंग होने पर शिव जी को भयंकर क्रोध आया। उन्होंने तुरंत अपना तीसरा नेत्र खोला, और उससे निकली आग ने पल भर में कामदेव को जलाकर भस्म कर दिया। कामदेव की पत्नी रति के रोने पर शिव जी ने कहा कि कामदेव अब बिना शरीर के हर प्राणी के मन में वास करेंगे। यह कथा हमें सिखाती है कि जब इंसान की चेतना (तीसरा नेत्र) जागृत होती है, तो उसके भीतर की सभी वासनाएं (कामदेव) अपने आप भस्म हो जाती हैं।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "भगवान शिव का तीसरा नेत्र कब खुला?", "image_prompt": "Close up of Lord Shiva''s face with the third eye glowing bright orange, intense divine aura, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "सती की मृत्यु के बाद शिव ध्यान में थे।", "image_prompt": "Lord Shiva meditating deeply in the snowy peaks of Mount Kailash, peaceful and isolated, cinematic, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "इधर तारकासुर का आतंक बढ़ रहा था।", "image_prompt": "A giant terrifying demon Tarakasura roaring, dark and fiery background, mythological art, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "देवताओं ने कामदेव को भेजा।", "image_prompt": "Kamadeva, the Hindu god of love, holding a bow made of sugarcane and arrows of flowers, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "कामदेव ने शिव पर फूलों के बाण चलाए।", "image_prompt": "Kamadeva shooting glowing floral arrows towards meditating Lord Shiva, magical colorful dust, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "शिव जी की तपस्या भंग हो गई।", "image_prompt": "Lord Shiva opening his two eyes, looking slightly disturbed and angry, cold blue tones, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "उन्हें भयंकर क्रोध आया।", "image_prompt": "Shiva''s face turning furious, the cosmic third eye on his forehead starting to crack open and emit fire, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "और उन्होंने अपना तीसरा नेत्र खोल दिया!", "image_prompt": "A massive beam of fiery energy shooting out from Shiva''s third eye, epic dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "कामदेव पल भर में भस्म हो गए।", "image_prompt": "Kamadeva turning into a pile of grey ashes amidst blazing fire, tragic and powerful, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "रति के विलाप पर शिव ने वरदान दिया...", "image_prompt": "Goddess Rati weeping near the ashes, Lord Shiva looking at her with compassion, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "कि कामदेव अब बिना शरीर के वास करेंगे।", "image_prompt": "A glowing ethereal form of Kamadeva rising as pure energy, entering the hearts of beings, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "चेतना जागने पर वासनाएं भस्म हो जाती हैं।", "image_prompt": "A glowing third eye symbol radiating spiritual light, destroying dark shadows, spiritual awakening concept, 9:16", "approx_sec": 5.0}]}' WHERE id = 'shiva_third_eye_kama';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "ramayana_hanuman_sun", "title": "जब हनुमान जी ने सूर्य को फल समझा", "category": "रामायण कथा", "script_hi": "जब हनुमान जी ने सूर्य को फल समझा। बचपन में एक दिन बाल हनुमान को बहुत ज़ोर की भूख लगी। उन्होंने आसमान में देखा तो उन्हें लाल चमकता हुआ सूर्य दिखाई दिया। हनुमान जी को लगा कि वह कोई बहुत बड़ा और मीठा फल है। वे बिना कुछ सोचे-समझे उड़कर आसमान में चले गए और सूर्य देव को अपने मुंह में रख लिया। पूरे ब्रह्मांड में अंधेरा छा गया। यह देखकर देवराज इंद्र घबरा गए और उन्होंने अपने वज्र से हनुमान जी की ठोड़ी (हनु) पर प्रहार किया। प्रहार से हनुमान जी बेहोश होकर धरती पर गिर पड़े। जब पवन देव ने यह देखा, तो उन्होंने क्रोधित होकर पूरे संसार की हवा रोक दी। तब सभी देवताओं ने आकर पवन देव से क्षमा मांगी और बाल हनुमान को अनेक दिव्य वरदान दिए। इसी वज्र के प्रहार के कारण उनका नाम ''हनुमान'' पड़ा।", "estimated_speech_sec": 70.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "जब हनुमान जी ने सूर्य को फल समझा।", "image_prompt": "Cute baby Hanuman looking up at the glowing red sun in the sky with hungry eyes, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "बाल हनुमान को बहुत भूख लगी थी।", "image_prompt": "Baby Hanuman holding his stomach, sitting on a mountain peak, ancient India setting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "वे उड़कर आसमान में चले गए...", "image_prompt": "Baby Hanuman flying upwards towards the giant blazing sun, dynamic comic style mythology, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "और सूर्य को अपने मुंह में रख लिया।", "image_prompt": "Baby Hanuman with puffed cheeks having swallowed the glowing sun, the sky turning dark, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "पूरे ब्रह्मांड में अंधेरा छा गया।", "image_prompt": "The entire cosmos in pitch darkness, stars visible, panicked gods in the background, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "इंद्र देव घबरा गए।", "image_prompt": "Lord Indra riding his white elephant Airavata, looking panicked and holding the lightning Vajra, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "उन्होंने अपने वज्र से प्रहार किया।", "image_prompt": "Indra throwing a glowing lightning bolt (Vajra) towards baby Hanuman in the sky, dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "हनुमान जी धरती पर गिर पड़े।", "image_prompt": "Baby Hanuman falling unconscious towards the earth, glowing aura fading, sad mythological scene, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "पवन देव क्रोधित हो गए।", "image_prompt": "Vayu (Wind God) holding unconscious baby Hanuman in his arms, looking extremely furious, storm brewing, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "संसार की हवा रुक गई।", "image_prompt": "Nature suffocating, trees completely still, beings gasping for air, atmospheric tension, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "देवताओं ने क्षमा मांगी और वरदान दिए।", "image_prompt": "Brahma, Shiva, and other gods blessing baby Hanuman with glowing divine light, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "इसी प्रहार से नाम पड़ा ''हनुमान''!", "image_prompt": "A majestic portrait of Lord Hanuman with a glowing aura, representing his immense strength and devotion, 9:16", "approx_sec": 5.0}]}' WHERE id = 'ramayana_hanuman_sun';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "jyotish_sade_sati_shani", "title": "शनिदेव की साढ़े साती का सच", "category": "नक्षत्र एवं ग्रह ज्ञान", "script_hi": "शनिदेव की साढ़े साती का असली सच क्या है? लोग साढ़े साती का नाम सुनते ही कांपने लगते हैं। ऐसा लगता है जैसे यह कोई बहुत बड़ा श्राप हो। लेकिन वैदिक ज्योतिष के अनुसार, शनि देव कोई क्रूर ग्रह नहीं हैं, बल्कि वे हमारे कर्मों के न्यायाधीश (Judge) हैं। साढ़े साती वह सात-साढ़े सात साल का समय होता है, जब शनि देव आपकी कुंडली के चंद्रमा के ऊपर से गुजरते हैं। इस दौरान वे आपके जीवन से सभी झूठे रिश्तों, अहंकार और गलत आदतों को निचोड़ कर बाहर निकाल देते हैं। जो लोग ईमानदार और मेहनती हैं, उन्हें साढ़े साती में रंक से राजा बनते हुए भी देखा गया है। शनिदेव बस यह चाहते हैं कि आप सोने की तरह तप कर निखरें। इसलिए साढ़े साती से डरने के बजाय, अपने कर्मों को शुद्ध रखें। शनिदेव दंड नहीं, बल्कि न्याय देते हैं।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "शनिदेव की साढ़े साती का असली सच?", "image_prompt": "Lord Shani Dev sitting on his crow chariot, holding a staff, dark cosmic blue and black aura, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "लोग इसका नाम सुनते ही डर जाते हैं।", "image_prompt": "A silhouette of a person looking terrified at a giant glowing ring of Saturn in the sky, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "मानो यह कोई बहुत बड़ा श्राप हो।", "image_prompt": "Dark storm clouds gathering over a lonely house, lightning strikes, eerie atmosphere, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "लेकिन शनि देव क्रूर नहीं हैं...", "image_prompt": "A glowing majestic face of Lord Shani with eyes of deep wisdom and justice, not anger, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "वे हमारे कर्मों के न्यायाधीश हैं।", "image_prompt": "A massive glowing scale of justice balancing karma, cosmic background, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "साढ़े साती वह समय है जब...", "image_prompt": "A glowing clock transitioning through 7.5 years, astronomical elements, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "शनि आपकी कुंडली के चंद्रमा से गुजरते हैं।", "image_prompt": "The dark planet Saturn slowly eclipsing the glowing Moon in space, astrology chart lines overlay, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "वे झूठे रिश्तों और अहंकार को तोड़ते हैं।", "image_prompt": "A glass mirror shattering, revealing a pure golden light behind it, symbolic art, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "ईमानदार लोगों को रंक से राजा बनाते हैं।", "image_prompt": "A poor man working hard, transitioning into a successful king-like figure wearing a crown, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "वे चाहते हैं कि आप सोने की तरह तपें।", "image_prompt": "Liquid gold being purified in a glowing crucible, intense fire, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "इसलिए साढ़े साती से डरें नहीं।", "image_prompt": "A person meditating calmly in the middle of a heavy storm, protected by a blue aura, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "शनिदेव दंड नहीं, न्याय देते हैं।", "image_prompt": "Lord Shani raising his hand in blessing (Abhaya Mudra), radiating protective and just energy, 9:16", "approx_sec": 6.0}]}' WHERE id = 'jyotish_sade_sati_shani';
